INSERT INTO saly.evidencias(codigo,tipo,titulo,descripcion,referencia,fecha_evidencia,hechos,estado) VALUES ('SALY-CREATIVE-RESEARCH-E11-V02','INVESTIGACION_REFERENCIAL','Chulvi et al. — Design creativity in AI: Using the SCAMPER method (AI EDAM, 2025)','22 estudiantes de ingeniería de diseño y GPT-4 abordaron dos problemas conceptuales con SCAMPER; el estudio identifica potencial de inspiración novedosa y dificultades para discernir factibilidad.','https://doi.org/10.1017/S0890060425100036','2025-05-13'::date,'{"limitation":"Comparación en problemas de ingeniería; no demuestra efecto causal frente a GPT-4 sin SCAMPER ni transferencia a interfaces SALY.","source_review_level":"PRIMARY_PUBLICATION_REVIEW","transfer_validated":false}'::jsonb,'REFERENCIAL');
INSERT INTO saly.evidencias(codigo,tipo,titulo,descripcion,referencia,fecha_evidencia,hechos,estado) VALUES ('SALY-CREATIVE-RESEARCH-E12-V02','INVESTIGACION_REFERENCIAL','Hu et al. — Aesthetic preference and gaze-based visual attention in atlas-cover design (PLOS ONE, 2026)','Diseño factorial 2×2×2, 40 participantes válidos; estilo, armonía y layout afectaron atractivo, pero no se observaron asociaciones robustas entre atractivo y cuatro indicadores de mirada después de corrección.','https://doi.org/10.1371/journal.pone.0359864','2026-10-08'::date,'{"limitation":"Portadas de atlas y estímulos específicos; no extrapolar preferencias ni atención a fintech.","source_review_level":"PRIMARY_PUBLICATION_REVIEW","transfer_validated":false}'::jsonb,'REFERENCIAL');
INSERT INTO saly.evidencias(codigo,tipo,titulo,descripcion,referencia,fecha_evidencia,hechos,estado) VALUES ('SALY-CREATIVE-RESEARCH-E13-V02','INVESTIGACION_REFERENCIAL','Shen, Shamir e Igarashi — LayoutRectifier (Computer Graphics Forum, 2025)','Método de rectificación de layouts generados por búsqueda discreta de grillas y restricciones de contención; aborda desalineación, solapamientos no deseados y contención.','https://doi.org/10.1111/cgf.70273','2025-10-11'::date,'{"limitation":"Algoritmo sobre cajas estructuradas; no asegura que un generador raster respete coordenadas o legibilidad.","source_review_level":"PRIMARY_PUBLICATION_REVIEW","transfer_validated":false}'::jsonb,'REFERENCIAL');
INSERT INTO saly.evidencias(codigo,tipo,titulo,descripcion,referencia,fecha_evidencia,hechos,estado) VALUES ('SALY-CREATIVE-RESEARCH-E14-V02','INVESTIGACION_REFERENCIAL','DesignCritic — Confidence-Banded Calibration and Principle-Aware Auditing (IEEE Access, 2026)','En 4800 pares de jerarquía visual de TASTE, Qwen3.5-9B pasa de 53,25% a 59,65% con calibración y principios; persisten desacuerdos, se estudia transferencia externa.','https://doi.org/10.1109/ACCESS.2026.3730226','2026-09-02'::date,'{"limitation":"No sustituye diseño humano. La calibración depende del evaluador y conjunto; no importar umbrales ni cifras como precisión SALY.","source_review_level":"PRIMARY_PUBLICATION_REVIEW","transfer_validated":false}'::jsonb,'REFERENCIAL');
INSERT INTO saly.evidencias(codigo,tipo,titulo,descripcion,referencia,fecha_evidencia,hechos,estado) VALUES ('SALY-CREATIVE-RESEARCH-E15-V02','INVESTIGACION_REFERENCIAL','Možina et al. — Effects of Pictogram and Typeface Complexity on Visual Attention (Journal of Eye Movement Research, 2026)','Estudio eye-tracking con 90 participantes sobre complejidad de pictograma y tipografía en tres categorías de comunicación.','https://doi.org/10.3390/jemr19040073','2026-07-07'::date,'{"limitation":"La congruencia se investiga en estímulos específicos; no establece una tipografía universal para interfaces.","source_review_level":"PRIMARY_PUBLICATION_REVIEW","transfer_validated":false}'::jsonb,'REFERENCIAL');
INSERT INTO saly.evidencias(codigo,tipo,titulo,descripcion,referencia,fecha_evidencia,hechos,estado) VALUES ('SALY-CREATIVE-RESEARCH-E16-V02','INVESTIGACION_REFERENCIAL','Visual attention and perceived attractiveness in scientific posters (Thinking Skills and Creativity, 2026)','Estudio de atención visual en pósteres científicos reporta ventajas de densidad textual moderada y proporción equilibrada de figuras; extremos densos o dispersos pueden perjudicar procesamiento.','https://doi.org/10.1016/j.tsc.2026.102201','2026-09-01'::date,'{"limitation":"Medio de póster científico, no interfaz móvil; no trasladar porcentajes de ocupación ni tamaños como norma.","source_review_level":"PRIMARY_PUBLICATION_REVIEW","transfer_validated":false}'::jsonb,'REFERENCIAL');
INSERT INTO saly.evidencias(codigo,tipo,titulo,descripcion,referencia,fecha_evidencia,hechos,estado) VALUES ('SALY-CREATIVE-RESEARCH-E17-V02','INVESTIGACION_REFERENCIAL','Seo Hye — A Study on the Visual Hierarchy in Typography Education in the Digital Age (JSSDJ, 2025)','Estudio educativo con experimentos a lo largo de dos años sobre jerarquía tipográfica y aplicación docente.','https://doi.org/10.11247/jssdj.72.2_45','2025-09-30'::date,'{"limitation":"Aprendizaje humano y contexto educativo; no evidencia causal de mejora de una skill LLM.","source_review_level":"PRIMARY_PUBLICATION_REVIEW","transfer_validated":false}'::jsonb,'REFERENCIAL');
DO $seed$ DECLARE p visual.knowledge_module_versions%ROWTYPE; d saly.documentos%ROWTYPE; new_id bigint; raw bytea; pins jsonb; BEGIN
 SELECT * INTO STRICT p FROM visual.knowledge_module_versions WHERE business_code='SALY' AND module_code='K01' AND version='0.1' AND state='CANDIDATE';
 SELECT * INTO STRICT d FROM saly.documentos WHERE id=p.document_id;
 IF p.document_sha256 IS DISTINCT FROM '5c39a7648f17d01dc9364299ad65d4bb9d47d06f916da5351faa121ff72693ba' OR d.sha256 IS DISTINCT FROM p.document_sha256 OR encode(extensions.digest(d.contenido,'sha256'),'hex') IS DISTINCT FROM p.document_sha256 THEN RAISE EXCEPTION 'DEPTH_BASELINE_DRIFT'; END IF;
 SELECT jsonb_object_agg(e.codigo,visual.knowledge_evidence_digest_v1(e)) INTO pins FROM saly.evidencia_documentos l JOIN saly.evidencias e ON e.id=l.evidencia_id WHERE l.documento_id=d.id AND l.relacion='REFERENCIA_CONTRASTADA' AND e.estado='REFERENCIAL';
 IF pins IS DISTINCT FROM p.evidence_pins THEN RAISE EXCEPTION 'DEPTH_EVIDENCE_DRIFT'; END IF;
 raw:=d.contenido||convert_to('
### Ampliación v0.2 — Dirección conceptual y semiótica aplicada
**Técnica A: matriz intención → signo → interpretación → riesgo.** Extraer función, público conocido, mensaje primario, acción, tono y condiciones de uso. Para cada signo propuesto distinguir su significado literal (p. ej. escudo) de connotaciones posibles (seguridad, garantía); evaluar si esas inferencias están respaldadas y si el contexto puede invertir su significado. Separar convención del sector, activo oficial y decisión creativa. No usar iconografía que sugiera garantía, autorización o beneficio no acreditado.
**Técnica B: tesis y narrativa visual.** Definir una frase conceptual verificable y traducirla a secuencia de lectura: reconocimiento, comprensión, acción. Para cada fase asignar foco, contraste, tratamiento tipográfico, relación figura/fondo y profundidad; justificar los recursos por la función. En uso informativo priorizar comprensión y reducir estímulos competitivos; en promoción explorar una metáfora visual pertinente si no modifica la oferta. No confundir escena con flujo de interacción.
**Técnica C: vocabulario estético comparado.** Construir dos familias de tratamiento distintas (por ejemplo documental sobrio vs editorial cálido) con diferencias explícitas en forma, escala, ritmo, textura, iluminación y lenguaje iconográfico; excluir atributos bloqueados, contrastar coherencia interna y adecuación al brief. Si el trabajo es corrección localizada, no introducir tesis nueva.
**Selección:** elegir A cuando hay riesgo de interpretación, B cuando el mensaje requiere recorrido, C cuando existe libertad de lenguaje. Se pueden combinar; no exigir más alternativas si no cambian la decisión. E12 distingue atractivo de mirada; E15 y E17 apoyan estudiar relaciones tipográficas y perceptuales, no inferir efectos universales. Los métodos A–C son síntesis operativas candidatas, no algoritmos validados por esos estudios.
**Ejercicio congelado:** una tarjeta de disponible y una campaña de beneficios con misma identidad. Entregar dos tesis, matriz signo/interpretación y relato visual elegido. Negativo: escudo que implica garantía financiera inexistente, o una promoción que compite visualmente con el saldo. Métricas: reconocimiento correcto del mensaje y acción por revisores, asociaciones indebidas por signo, preferencia estética por separado. Sin público conocido, registrar hipótesis; no declarar emoción observada.

**Estado:** CANDIDATE. Transferencia no validada. Conserva el fundamento y límites v0.1; la ampliación añade técnicas, no permisos.
','UTF8');
